def button(label="Let’s talk", href="/get-started/", secondary=False):
    return f'<a class="button{" secondary" if secondary else ""}" href="{href}">{label}{ARROW}</a>'

def eyebrow(text):
    return f'<p class="eyebrow"><span aria-hidden="true">+</span> {text}</p>'

def closing():
    return f'''<section class="closing"><div class="wrap closing-inner"><div>{eyebrow("A useful place to start")}<h2>What’s getting<br>in the way?</h2></div><div><p>Tell us about the work, the people doing it, and what you want to change. We’ll work out the next step together.</p>{button("Start a conversation")}</div></div></section>'''

def pagehero(label, title, description, extra=""):
    return f'<section class="page-hero wrap">{eyebrow(label)}<h1>{title}</h1><p class="lede">{description}</p>{extra}</section>'

