def layout(slug,title,desc,body):
    canonical = 'https://remedys.ai/' + (slug+'/' if slug else '')
    nav = ''.join(f'<a href="/{s}/"'+(' aria-current="page"' if s==slug else '')+f'>{label}</a>' for s,label in [("services","Services"),("implementation","Approach"),("about","About")])
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | Remedys.ai</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="theme-color" content="#f4f3ed"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{html.escape(title,quote=True)} | Remedys.ai"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://remedys.ai/assets/brand/social.png"><meta property="og:image:alt" content="Remedys"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" type="image/svg+xml" href="/assets/brand/r-black.svg"><link rel="apple-touch-icon" href="/assets/brand/icon-180.png"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head>
<body data-page="{slug or 'home'}"><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Remedys home"><img src="/assets/brand/remedys-black.svg" width="172" height="41" alt="Remedys"></a><nav class="primary-nav" aria-label="Main navigation">{nav}<a class="nav-contact" href="/get-started/">Let’s talk {ARROW}</a></nav><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-nav" hidden>Menu <span aria-hidden="true">+</span></button></div><nav id="mobile-nav" class="mobile-nav wrap" aria-label="Mobile navigation" hidden>{nav}<a href="/get-started/">Let’s talk {ARROW}</a><a href="/contact/">Contact</a></nav></header><main id="main">{body}</main><footer class="site-footer wrap"><div class="footer-top"><a class="footer-brand" href="/" aria-label="Remedys home"><img src="/assets/brand/remedys-black.svg" width="260" height="62" alt="Remedys"></a><p>Clear thinking.<br>Practical AI.</p><a class="text-link" href="mailto:hello@remedys.ai">hello@remedys.ai {ARROW}</a></div><div class="footer-bottom"><span>© 2026 Remedys.ai</span><nav aria-label="Footer navigation"><a href="/services/">Services</a><a href="/manifesto/">Principles</a><a href="/contact/">Contact</a><a href="/privacy/">Privacy</a></nav><a href="#top" data-back-top>Back to top ↑</a></div></footer></body></html>'''.replace('<body data-page=', '<body id="top" data-page=')

